fn sse_parser() -> &'static str {
    r#"
    /** Lazy SSE payload framing. Metadata/comment fields are not data. */
    private static java.util.stream.Stream<String> ssePayloads(java.util.stream.Stream<String> lines) {
        var iterator = lines.iterator();
        var splitter = new java.util.Spliterators.AbstractSpliterator<String>(Long.MAX_VALUE, java.util.Spliterator.ORDERED | java.util.Spliterator.NONNULL) {
            @Override public boolean tryAdvance(java.util.function.Consumer<? super String> action) {
                var data = new java.util.ArrayList<String>();
                while (iterator.hasNext()) {
                    var line = iterator.next();
                    if (line.isEmpty()) {
                        if (!data.isEmpty()) { action.accept(String.join("\n", data)); return true; }
                    } else if (line.equals("data")) { data.add(""); }
                    else if (line.startsWith("data:")) {
                        var value = line.substring(5);
                        data.add(value.startsWith(" ") ? value.substring(1) : value);
                    }
                }
                if (!data.isEmpty()) { action.accept(String.join("\n", data)); return true; }
                return false;
            }
        };
        return java.util.stream.StreamSupport.stream(splitter, false).onClose(lines::close);
    }
"#
}

fn declared_error_responses(operation: &Operation) -> Vec<&OperationResponse> {
    operation
        .responses
        .iter()
        .filter(|response| {
            response
                .status
                .parse::<u16>()
                .is_ok_and(|status| !(200..300).contains(&status))
        })
        .collect()
}

fn declared_error_schema(response: &OperationResponse) -> Option<&SchemaValue> {
    response
        .media_types
        .iter()
        .find(|media| is_json_media(&media.content_type))
        .and_then(|media| media.schema.as_ref())
}

fn java_error_name(operation: &Operation, response: &OperationResponse) -> String {
    format!(
        "{}Status{}Exception",
        type_name(&operation.id),
        response.status
    )
}

fn java_error_mapper_name(operation: &Operation) -> String {
    format!("map{}Error", type_name(&operation.id))
}

/// Error types are nested under Client so the package retains one public
/// transport exception file while callers can catch operation/status-specific
/// classes. A malformed declared error body remains available as raw text.
fn render_declared_error_types(output: &mut String, api: &Api) {
    for operation in &api.operations {
        let responses = declared_error_responses(operation);
        if responses.is_empty() {
            continue;
        }
        let mapper = java_error_mapper_name(operation);
        let _ = writeln!(
            output,
            "    private RuntimeException {mapper}(ApiException error) {{\n        return switch (error.statusCode()) {{"
        );
        for response in &responses {
            let status = &response.status;
            let error = java_error_name(operation, response);
            if let Some(schema) = declared_error_schema(response) {
                let class = response_class(schema);
                let _ = writeln!(
                    output,
                    "            case {status} -> new {error}(error, decodeDeclaredError(error.responseBody(), {class}.class));"
                );
            } else {
                let _ = writeln!(output, "            case {status} -> new {error}(error);");
            }
        }
        output.push_str("            default -> error;\n        };\n    }\n\n");
        for response in responses {
            let error = java_error_name(operation, response);
            if let Some(schema) = declared_error_schema(response) {
                let body = operation_response_type(schema);
                let _ = writeln!(
                    output,
                    "    public static final class {error} extends ApiException {{\n        private final {body} body;\n        private {error}(ApiException source, {body} body) {{ super(source.statusCode(), source.responseBody(), source.retryAfter(), source.retryAfterMillis()); this.body = body; }}\n        public {body} body() {{ return body; }}\n    }}\n"
                );
            } else {
                let _ = writeln!(
                    output,
                    "    public static final class {error} extends ApiException {{\n        private {error}(ApiException source) {{ super(source.statusCode(), source.responseBody(), source.retryAfter(), source.retryAfterMillis()); }}\n    }}\n"
                );
            }
        }
    }
    output.push_str("    private <T> T decodeDeclaredError(String response, Class<T> type) {\n        if (response == null || response.isBlank()) return null;\n        try { return mapper.readValue(response, type); } catch (JsonProcessingException ignored) { return null; }\n    }\n\n");
}

fn operation_parameters(operation: &Operation) -> Vec<&OperationParameter> {
    operation
        .parameters
        .iter()
        .filter(|parameter| {
            matches!(
                parameter.location.as_str(),
                "path" | "query" | "header" | "cookie" | "querystring"
            )
        })
        .collect()
}

fn request_body_schema(operation: &Operation) -> Option<&SchemaValue> {
    operation.request_body.as_ref().and_then(|body| {
        body.media_types
            .iter()
            .find(|media| media.content_type.contains("json"))
            .or_else(|| body.media_types.first())
            .and_then(|media| media.schema.as_ref())
    })
}

fn request_content_type(operation: &Operation) -> Option<&str> {
    operation
        .request_body
        .as_ref()?
        .media_types
        .iter()
        .find(|media| media.content_type.contains("json"))
        .or_else(|| operation.request_body.as_ref()?.media_types.first())
        .map(|media| media.content_type.as_str())
}

fn is_json_media(content_type: &str) -> bool {
    content_type.contains("json") || content_type.ends_with("+json")
}

fn is_sse_media(content_type: &str) -> bool {
    content_type.eq_ignore_ascii_case("text/event-stream")
}

fn request_body_is_binary(operation: &Operation) -> bool {
    request_content_type(operation).is_some_and(|content_type| !is_json_media(content_type))
}

enum ResponseSurface<'a> {
    Json(&'a SchemaValue),
    Binary,
    Sse,
    Empty,
}

/// Pick the actual successful representation rather than treating every
/// OpenAPI response as JSON. This keeps download and event endpoints usable
/// without a hand-written transport escape hatch.
fn response_surface(operation: &Operation) -> ResponseSurface<'_> {
    let Some(response) = operation
        .responses
        .iter()
        .find(|response| response.status.starts_with('2'))
        .or_else(|| {
            operation
                .responses
                .iter()
                .find(|response| response.status == "default")
        })
    else {
        return ResponseSurface::Empty;
    };
    let Some(media) = response
        .media_types
        .iter()
        .find(|media| is_sse_media(&media.content_type))
        .or_else(|| {
            response
                .media_types
                .iter()
                .find(|media| is_json_media(&media.content_type))
        })
        .or_else(|| response.media_types.first())
    else {
        return ResponseSurface::Empty;
    };
    if is_sse_media(&media.content_type) {
        ResponseSurface::Sse
    } else if is_json_media(&media.content_type) {
        media
            .schema
            .as_ref()
            .map(ResponseSurface::Json)
            .unwrap_or(ResponseSurface::Empty)
    } else {
        ResponseSurface::Binary
    }
}

fn parameter_json_content(parameter: &OperationParameter) -> bool {
    poolster_core::openapi32::parameter_content(parameter)
        .ok()
        .and_then(|items| items.into_iter().next())
        .is_some_and(|content| {
            content.content_type == "application/json" || content.content_type.ends_with("+json")
        })
}
fn parameter_type(parameter: &OperationParameter) -> String {
    if parameter.location == "querystring" {
        return "String".into();
    }
    parameter
        .schema
        .as_ref()
        .map(java_type)
        .unwrap_or_else(|| "java.lang.Object".to_owned())
}

fn response_class(schema: &SchemaValue) -> String {
    match &schema.kind {
        SchemaKind::Reference { reference } => {
            type_name(reference.rsplit('/').next().unwrap_or(reference))
        }
        SchemaKind::String => "String".into(),
        SchemaKind::Boolean => "Boolean".into(),
        SchemaKind::Integer => "Long".into(),
        SchemaKind::Number => "Double".into(),
        _ => "JsonNode".into(),
    }
}

/// Jackson's class-token API can preserve named models and scalar responses.
/// Arrays and anonymous composite schemas need a `TypeReference`; Poolster emits
/// those as `JsonNode` instead of producing generic Java that cannot compile.
fn operation_response_type(schema: &SchemaValue) -> String {
    match &schema.kind {
        SchemaKind::Reference { .. }
        | SchemaKind::String
        | SchemaKind::Boolean
        | SchemaKind::Integer
        | SchemaKind::Number => java_type(schema),
        _ => "JsonNode".into(),
    }
}

fn java_type(value: &SchemaValue) -> String {
    match &value.kind {
        SchemaKind::Any
        | SchemaKind::OneOf { .. }
        | SchemaKind::AnyOf { .. }
        | SchemaKind::AllOf { .. }
        | SchemaKind::Not { .. } => "JsonNode".into(),
        SchemaKind::Null => "Void".into(),
        SchemaKind::Boolean => "Boolean".into(),
        SchemaKind::Integer => "Long".into(),
        SchemaKind::Number => "Double".into(),
        SchemaKind::String => "String".into(),
        SchemaKind::Array { items } => format!("List<{}>", java_type(items)),
        SchemaKind::Object {
            additional_properties,
            ..
        } => match additional_properties {
            AdditionalProperties::Schema { value } => format!("Map<String, {}>", java_type(value)),
            _ => "JsonNode".into(),
        },
        SchemaKind::Reference { reference } => {
            type_name(reference.rsplit('/').next().unwrap_or(reference))
        }
    }
}

